import os
import json
from typing import Any, Dict, List, Optional

from pydantic import BaseModel, Field, ValidationError, condecimal, constr
from openai import OpenAI


class Confidence(BaseModel):
    value: condecimal(ge=0, le=1) = Field(..., description="Confidence score between 0 and 1")


class ExtractedDocument(BaseModel):
    document_type: constr(strip_whitespace=True, min_length=1)
    invoice_number: Optional[constr(strip_whitespace=True, min_length=1)] = None
    invoice_date: Optional[constr(strip_whitespace=True, min_length=1)] = None
    vendor_name: Optional[constr(strip_whitespace=True, min_length=1)] = None
    total_amount: Optional[float] = None
    currency: Optional[constr(strip_whitespace=True, min_length=1)] = None
    fields_confidence: Dict[str, Confidence]

    def validate_required_fields(self, required_fields: List[str]) -> None:
        missing = []
        low_confidence = []
        for field_name in required_fields:
            if getattr(self, field_name, None) in (None, ""):
                missing.append(field_name)
            conf = self.fields_confidence.get(field_name)
            if conf is None:
                low_confidence.append(f"{field_name}:missing_confidence")
        if missing or low_confidence:
            raise ValueError(
                json.dumps(
                    {
                        "missing_required_fields": missing,
                        "confidence_issues": low_confidence,
                    }
                )
            )


def extract_structured_document(
    document_text: str,
    required_fields: List[str],
    min_confidence: float = 0.7,
) -> Dict[str, Any]:
    client = OpenAI(api_key=os.environ["OPENAI_API_KEY"])

    schema = {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "document_type": {"type": "string"},
            "invoice_number": {"type": ["string", "null"]},
            "invoice_date": {"type": ["string", "null"]},
            "vendor_name": {"type": ["string", "null"]},
            "total_amount": {"type": ["number", "null"]},
            "currency": {"type": ["string", "null"]},
            "fields_confidence": {
                "type": "object",
                "additionalProperties": {
                    "type": "object",
                    "additionalProperties": False,
                    "properties": {
                        "value": {"type": "number", "minimum": 0, "maximum": 1}
                    },
                    "required": ["value"],
                },
            },
        },
        "required": ["document_type", "fields_confidence"],
    }

    response = client.responses.create(
        model="gpt-4.1-mini",
        input=[
            {
                "role": "system",
                "content": (
                    "Extract structured fields from the provided document text. "
                    "Return only valid JSON matching the schema. "
                    "Provide a confidence score between 0 and 1 for every extracted field present in the response. "
                    "If a field cannot be determined, return null for the field and still include its confidence if possible."
                ),
            },
            {
                "role": "user",
                "content": f"Required fields: {required_fields}\n\nDocument text:\n{document_text}",
            },
        ],
        text={
            "format": {
                "type": "json_schema",
                "name": "document_extraction",
                "schema": schema,
                "strict": True,
            }
        },
    )

    parsed = json.loads(response.output_text)
    extracted = ExtractedDocument.model_validate(parsed)
    extracted.validate_required_fields(required_fields)

    confidence_failures = {}
    for field_name in required_fields:
        conf = extracted.fields_confidence.get(field_name)
        if conf is None or float(conf.value) < min_confidence:
            confidence_failures[field_name] = None if conf is None else float(conf.value)

    if confidence_failures:
        raise ValueError(
            json.dumps(
                {
                    "message": "Required fields below minimum confidence",
                    "min_confidence": min_confidence,
                    "failures": confidence_failures,
                }
            )
        )

    return extracted.model_dump()


def validate_extraction_payload(payload: Dict[str, Any], required_fields: List[str], min_confidence: float = 0.7) -> Dict[str, Any]:
    try:
        extracted = ExtractedDocument.model_validate(payload)
        extracted.validate_required_fields(required_fields)
    except (ValidationError, ValueError) as e:
        raise ValueError(f"Invalid extraction payload: {e}") from e

    below_threshold = {}
    for field_name in required_fields:
        conf = extracted.fields_confidence.get(field_name)
        if conf is None or float(conf.value) < min_confidence:
            below_threshold[field_name] = None if conf is None else float(conf.value)

    if below_threshold:
        raise ValueError(
            json.dumps(
                {
                    "message": "Validation failed: confidence below threshold",
                    "min_confidence": min_confidence,
                    "fields": below_threshold,
                }
            )
        )

    return extracted.model_dump()
